-- English localization and Grandmaster Severin diplomacy.

INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_CIV_DUAL_ORDER_DESC','The Dual Order'),
('TXT_KEY_CIV_DUAL_ORDER_SHORT_DESC','The Dual Order'),
('TXT_KEY_CIV_DUAL_ORDER_ADJECTIVE','Dual Order'),
('TXT_KEY_CIV_DUAL_ORDER_PEDIA','The Dual Order is a militant religious state founded on a deliberate equilibrium: faith gives the sword its purpose, and the sword protects the faith. Its chapter houses bind priest and soldier into one government, while its armies draw cohesion from a realm that continues to pray even at war.'),
('TXT_KEY_CIV5_DUAL_ORDER_HEADING_1','The Twin Mandates'),
('TXT_KEY_CIV5_DUAL_ORDER_TEXT_1','Neither altar nor arsenal may rule alone. Every chapter of the Order is charged to build both, and every Grandmaster is judged by the balance kept between them.'),
('TXT_KEY_CIV_DUAL_ORDER_STRATEGY','Build Barracks, Armories, and Temples to gain Production and Faith. Train military units in cities that contain both military and religious infrastructure to grant Zeal. Keep Faith per turn positive during wars to activate capped Balance Pressure, then use Golden Ages to accelerate military training. Divided Templars excel at finishing wounded enemies and fighting beside religious units; Halls of Concordance strengthen Faith, Production, Happiness, training, and Great General progress.'),

('TXT_KEY_LEADER_GRANDMASTER_SEVERIN','Grandmaster Severin'),
('TXT_KEY_LEADER_GRANDMASTER_SEVERIN_PEDIA','Severin rose through both halves of the Order: first as a field commander who refused needless slaughter, then as a canon who rejected piety without protection. His rule is austere, methodical, and devoted to the proposition that conviction and force must remain answerable to one another.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GRANDMASTER_SEVERIN_HEADING_1','The Keeper of Balance'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GRANDMASTER_SEVERIN_TEXT_1','Grandmaster Severin is remembered for rebuilding the chapter system after a generation of factional struggle. He required every military command to maintain a religious household and every major temple to support the defense of its province, creating the institutions now called the Twin Mandates.'),

('TXT_KEY_TRAIT_DUAL_ORDER_SHORT','Twin Mandates'),
('TXT_KEY_TRAIT_DUAL_ORDER_HELP','Barracks, Armories, Temples, and their unique replacements provide +1 [ICON_PRODUCTION] Production and +1 [ICON_PEACE] Faith. Normally trained military units gain Zeal when their city has both military-training and religious infrastructure. With positive Faith per turn, each active war grants +2% combat strength and +1% Production in all Cities, capped at five wars. During Golden Ages, Cities gain +25% Production toward military units and normally trained military units gain +5 XP.'),

('TXT_KEY_UNIT_DUAL_ORDER_DIVIDED_TEMPLAR','Divided Templar'),
('TXT_KEY_UNIT_DUAL_ORDER_DIVIDED_TEMPLAR_PEDIA','The Divided Templar embodies the martial half of the Order without severing it from the spiritual half. Its shield carries the realm''s divided field, the red sword of discipline, and the eagle of temporal protection.'),
('TXT_KEY_UNIT_DUAL_ORDER_DIVIDED_TEMPLAR_STRATEGY','A stronger but more expensive Longswordsman replacement. It begins with Cover I and Schism Strike: +20% attack strength against units below half health and +10% combat strength while adjacent to a friendly Great Prophet, Missionary, or Inquisitor.'),
('TXT_KEY_UNIT_DUAL_ORDER_DIVIDED_TEMPLAR_HELP','Replaces the Longswordsman. 23 [ICON_STRENGTH] Combat Strength and costs 10% more Production. Starts with Cover I and Schism Strike.'),

('TXT_KEY_BUILDING_DUAL_ORDER_HALL_CONCORDANCE','Hall of Concordance'),
('TXT_KEY_BUILDING_DUAL_ORDER_HALL_CONCORDANCE_PEDIA','The Hall of Concordance is equal parts armory, chapter house, and council chamber. Here military commanders and religious authorities administer the province together, keeping neither mandate beyond the scrutiny of the other.'),
('TXT_KEY_BUILDING_DUAL_ORDER_HALL_CONCORDANCE_STRATEGY','An Armory replacement that adds +3 Faith, +2 Production, and 5 additional XP to trained units. It provides +1 Happiness when the City follows the Dual Order''s founded religion and contributes +1 Great General Point per turn.'),
('TXT_KEY_BUILDING_DUAL_ORDER_HALL_CONCORDANCE_HELP','Replaces the Armory. Normal Armory effects, plus +3 [ICON_PEACE] Faith, +2 [ICON_PRODUCTION] Production, 5 additional XP, +1 [ICON_HAPPINESS_1] Happiness when the City follows your founded religion, and +1 Great General Point per turn.'),
('TXT_KEY_BUILDING_DUAL_ORDER_DUMMY','Dual Order Runtime Effect'),

('TXT_KEY_PROMOTION_DUAL_ORDER_ZEAL','Zeal'),
('TXT_KEY_PROMOTION_DUAL_ORDER_ZEAL_HELP','+10% Combat Strength while inside or adjacent to friendly territory. Heals 10 HP after killing an enemy unit. Persists through upgrades.'),
('TXT_KEY_PROMOTION_DUAL_ORDER_ZEAL_ACTIVE','Zeal: Defending the Faith'),
('TXT_KEY_PROMOTION_DUAL_ORDER_ZEAL_ACTIVE_HELP','This unit is inside or adjacent to friendly territory and receives +10% Combat Strength from Zeal.'),
('TXT_KEY_PROMOTION_DUAL_ORDER_BALANCE','Balance Pressure'),
('TXT_KEY_PROMOTION_DUAL_ORDER_BALANCE_HELP','Combat bonus from active wars while the Dual Order generates positive Faith per turn.'),
('TXT_KEY_PROMOTION_DUAL_ORDER_SCHISM_STRIKE','Schism Strike'),
('TXT_KEY_PROMOTION_DUAL_ORDER_SCHISM_STRIKE_HELP','+20% Combat Strength when attacking a unit below 50% HP. +10% Combat Strength while adjacent to a friendly Great Prophet, Missionary, or Inquisitor.'),
('TXT_KEY_PROMOTION_DUAL_ORDER_SCHISM_WOUNDED','Schism Strike: Wounded Target'),
('TXT_KEY_PROMOTION_DUAL_ORDER_SCHISM_WOUNDED_HELP','+20% Combat Strength while attacking a unit below 50% HP.'),
('TXT_KEY_PROMOTION_DUAL_ORDER_HOLY_SUPPORT','Schism Strike: Holy Support'),
('TXT_KEY_PROMOTION_DUAL_ORDER_HOLY_SUPPORT_HELP','+10% Combat Strength while adjacent to a friendly Great Prophet, Missionary, or Inquisitor.'),

('TXT_KEY_DUAL_ORDER_DAWN_OF_MAN','Grandmaster, the Dual Order awaits your command. For generations, faith and steel have stood together, neither permitted to dominate the other. The faithful give purpose to the warrior, and the warrior gives protection to the faithful.[NEWLINE][NEWLINE]Build halls where priest and soldier stand as equals. Let your armies march with conviction, and let every conflict strengthen the bond upon which your realm was founded.[NEWLINE][NEWLINE]Grandmaster Severin, can you preserve the balance of the Twin Mandates and forge an Order that will endure the test of time?'),

('TXT_KEY_CITY_DUAL_ORDER_1','Concordia'),('TXT_KEY_CITY_DUAL_ORDER_2','Severin''s Watch'),
('TXT_KEY_CITY_DUAL_ORDER_3','Vesperhold'),('TXT_KEY_CITY_DUAL_ORDER_4','Eisenkreuz'),
