('TXT_KEY_CITY_DUAL_ORDER_13','Faithward'),('TXT_KEY_CITY_DUAL_ORDER_14','Steelhaven'),
('TXT_KEY_CITY_DUAL_ORDER_15','Pilgrim''s Rest'),('TXT_KEY_CITY_DUAL_ORDER_16','Chapterhouse'),
('TXT_KEY_CITY_DUAL_ORDER_17','Canon''s Reach'),('TXT_KEY_CITY_DUAL_ORDER_18','Templar''s Ford'),
