INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_LEADER_DUAL_ORDER_FIRSTGREETING_1','You stand before the Dual Order. Speak with conviction, and keep steel from your hand unless you mean to use it.'),
('TXT_KEY_LEADER_DUAL_ORDER_GREETING_NEUTRAL_1','Faith governs. Steel ensures. Which matter brings you here?'),
('TXT_KEY_LEADER_DUAL_ORDER_GREETING_HOSTILE_1','Your purpose is divided, but not in balance.'),
('TXT_KEY_LEADER_DUAL_ORDER_DOW_1','Your disorder now threatens both altar and realm. The chapter banners will answer.'),
('TXT_KEY_LEADER_DUAL_ORDER_ATTACKED_1','You have chosen steel without purpose. We will show you why the two mandates stand together.'),
('TXT_KEY_LEADER_DUAL_ORDER_DEFEATED_1','The balance is broken. See that what follows is governed better than what came before.'),
('TXT_KEY_LEADER_DUAL_ORDER_PEACE_1','Let the swords rest while honest terms preserve what remains.'),
('TXT_KEY_LEADER_DUAL_ORDER_TRADE_ACCEPT_1','This exchange serves both duty and defense.'),
('TXT_KEY_LEADER_DUAL_ORDER_TRADE_REJECT_1','The scales do not balance.'),
('TXT_KEY_LEADER_DUAL_ORDER_DENOUNCED_1','Judgment without discipline is only noise.' );
